//! Replays teams_ts_vectors.json (outcomes of the real flag-off teamService,
//! regenerated by workTeamVectors.test.ts) through the Rust Team `work` ops.
use serde_json::{Map, Value, json};

use super::run_json;

fn vectors() -> Value {
    serde_json::from_str(include_str!("teams_ts_vectors.json")).expect("vectors parse")
}

fn run(op: &str, input: &Value, name: &Value) -> Value {
    let output = run_json(op, &input.to_string()).unwrap_or_else(|e| panic!("{op} {name}: {e}"));
    serde_json::from_str(&output).expect("output json")
}

/// `Object.fromEntries(pairs)` plus the pair names in order.
fn from_pairs(pairs: &Value) -> (Value, Vec<Value>) {
    let mut object = Map::new();
    let mut names = Vec::new();
    for pair in pairs.as_array().expect("pairs") {
        let name = pair[0].as_str().expect("pair name");
        object.insert(name.to_owned(), pair[1].clone());
        names.push(json!(name));
    }
    (Value::Object(object), names)
}

/// The page side of `teamView`: rebuilds `securityPolicy` and checks its key order.
fn team_view(case: &Value, mut out: Value) -> Value {
    if out.get("error").is_none() {
        let (policy, names) = from_pairs(&out["securityPolicy"]);
        assert_eq!(Value::Array(names), case["policy_keys"], "policy key order: {}", case["name"]);
        out["securityPolicy"] = policy;
    }
    out
}

/// The page side of `teamBilling`: a `decrypt` answer is retried with the recorded plaintext.
fn team_billing(case: &Value, out: Value) -> Value {
    if out.get("decrypt").is_none() {
        return out;
    }
    let mut input = case["input"].clone();
    input["decrypt"] = case["decrypt"].clone();
    let retried = run("teamBilling", &input, &case["name"]);
    assert!(retried.get("decrypt").is_none(), "a decrypt answer is final: {}", case["name"]);
    retried
}

/// The page side of `teamCreatedRecord`: `{ ...returned, ...Object.fromEntries(overrides) }`.
fn created_record(case: &Value, out: &Value) -> Value {
    let mut record = case["input"]["returned"].as_object().cloned().unwrap_or_default();
    let (overrides, names) = from_pairs(&out["overrides"]);
    let returned = record.clone();
    for (name, value) in overrides.as_object().expect("overrides") {
        record.insert(name.clone(), value.clone());
    }
    // New members land after the reply's own keys, in override order.
    let fresh = |keys: &[Value]| keys.iter().filter(|k| !returned.contains_key(k.as_str().expect("key"))).cloned().collect::<Vec<_>>();
    assert_eq!(fresh(&names), fresh(case["keys"].as_array().expect("keys")), "override order: {}", case["name"]);
    assert_eq!(out["team_id"], record["team_id"], "created team id: {}", case["name"]);
    Value::Object(record)
}

#[test]
fn decisions_and_paths_equal_typescript() {
    let doc = vectors();
    let decisions = doc["decisions"].as_array().expect("decisions");
    assert!(decisions.len() >= 50, "every decision case is recorded");
    for case in decisions {
        let op = case["op"].as_str().expect("op");
        let out = run(op, &case["input"], &case["name"]);
        let actual = match op {
            _ if case["expected"].get("error").is_some() => json!({ "error": out["error"] }),
            "teamView" => team_view(case, out),
            "teamBilling" => team_billing(case, out),
            "teamCreatedRecord" => created_record(case, &out),
            _ => out,
        };
        assert_eq!(actual, case["expected"], "{op}: {}", case["name"]);
    }
    for case in doc["paths"].as_array().expect("paths") {
        assert_eq!(run("teamPath", &case["input"], &case["name"]), case["expected"], "teamPath: {}", case["name"]);
    }
}

/// Applies the ordered steps like workRust.ts `buildWorkBody` with the test stub
/// (`sealed:<key byte>:<plaintext>`), recording encryption calls and member order.
fn assemble(case: &Value, request: &Value) -> (Value, Vec<Value>, Vec<Value>) {
    let expected_body = &case["expected"]["body"];
    let mut body = Map::new();
    let mut calls = Vec::new();
    let mut names = Vec::new();
    for step in request["steps"].as_array().expect("steps") {
        let name = step[0].as_str().expect("step name");
        let action = &step[1];
        let mut seal = |text: &str, role: &Value| {
            let byte = &case["keys"][role.as_str().expect("key role")];
            calls.push(json!([text, byte]));
            json!(format!("sealed:{byte}:{text}"))
        };
        let value = if let Some(value) = action.get("value") {
            value.clone()
        } else if let Some(text) = action.get("encrypt") {
            seal(text.as_str().expect("plaintext"), &action["key"])
        } else if let Some(member) = action.get("encrypt_input") {
            let text = case["encrypt_inputs"][member.as_str().expect("member")].as_str().expect("page json");
            seal(text, &action["key"])
        } else if let Some(pairs) = action.get("object") {
            let (object, keys) = from_pairs(pairs);
            assert_eq!(Value::Array(keys), case["expected"]["object_keys"][name], "{name} key order: {}", case["name"]);
            object
        } else {
            // Slots are page-made (wrapped keys, approval token, file): taken from the TS body.
            expected_body[action["slot"].as_str().expect("slot")].clone()
        };
        names.push(json!(name));
        body.insert(name.to_owned(), value);
    }
    (Value::Object(body), calls, names)
}

#[test]
fn request_bodies_equal_typescript() {
    let doc = vectors();
    let bodies = doc["bodies"].as_array().expect("bodies");
    assert!(bodies.len() >= 15, "every body case is recorded");
    for case in bodies {
        let op = case["op"].as_str().expect("op");
        let request = run(op, &case["input"], &case["name"]);
        if let Some(error) = case["expected"].get("error") {
            assert_eq!(request.get("error"), Some(error), "{op}: {}", case["name"]);
            continue;
        }
        assert_eq!(request["path"], case["expected"]["path"], "{op} path: {}", case["name"]);
        assert_eq!(request["method"], case["expected"]["method"], "{op} method: {}", case["name"]);
        let (body, calls, names) = assemble(case, &request);
        assert_eq!(body, case["expected"]["body"], "{op} body: {}", case["name"]);
        assert_eq!(Value::Array(names), case["expected"]["keys"], "{op} member order: {}", case["name"]);
        assert_eq!(Value::Array(calls), case["expected"]["encrypt_calls"], "{op} encryption order: {}", case["name"]);
    }
}

#[test]
fn unknown_team_ops_and_malformed_inputs_are_refused() {
    assert_eq!(run_json("teamNothing", "{}").unwrap_err(), "unknown_op:teamNothing");
    assert_eq!(run_json("teamView", "{}").unwrap_err(), "missing_field:record");
    assert_eq!(run_json("teamPath", r#"{"route":"other"}"#).unwrap_err(), "bad_field:route");
    assert_eq!(run_json("teamMemberProfiles", r#"{"plaintexts":[1]}"#).unwrap_err(), "bad_field:plaintexts");
    let missing_plaintext = json!({ "record": { "team_id": "t", "encrypted_name": "c" }, "fields": {} });
    assert_eq!(run_json("teamView", &missing_plaintext.to_string()).unwrap_err(), "missing_field:fields.encrypted_name");
}

#[test]
fn parse_int_and_numbers_follow_javascript() {
    use super::teams::{number, parse_int};
    assert_eq!(parse_int(" \u{feff}-12.9x"), -12.0);
    assert!(parse_int("abc").is_nan());
    assert!(parse_int("+").is_nan());
    assert!(parse_int(&"9".repeat(400)).is_infinite());
    assert_eq!(number(-0.0), json!(0));
    assert_eq!(number(f64::NAN), Value::Null);
    assert_eq!(number(4.5), json!(4.5));
}
